import heapq

def match(orders):
    trades = []
    book = {}  # id -> {'side', 'price', 'qty', 'seq', 'active'}
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = [0]

    def next_seq():
        seq_counter[0] += 1
        return seq_counter[0]

    def clean_buy_heap():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            rec = book.get(oid)
            if rec is None or not rec['active'] or rec['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            rec = book.get(oid)
            if rec is None or not rec['active'] or rec['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    def match_incoming(side, price, qty, incoming_id):
        # price is None means match any price (market order)
        nonlocal trades
        remaining = qty
        if side == 'buy':
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                sp, sseq, sid = sell_heap[0]
                if price is not None and sp > price:
                    break
                rec = book[sid]
                trade_qty = min(remaining, rec['qty'])
                trades.append([incoming_id, sid, sp, trade_qty])
                remaining -= trade_qty
                rec['qty'] -= trade_qty
                if rec['qty'] <= 0:
                    rec['active'] = False
                    heapq.heappop(sell_heap)
            return remaining
        else:
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                negbp, bseq, bid = buy_heap[0]
                bp = -negbp
                if price is not None and bp < price:
                    break
                rec = book[bid]
                trade_qty = min(remaining, rec['qty'])
                trades.append([bid, incoming_id, bp, trade_qty])
                remaining -= trade_qty
                rec['qty'] -= trade_qty
                if rec['qty'] <= 0:
                    rec['active'] = False
                    heapq.heappop(buy_heap)
            return remaining

    for order in orders:
        typ = order[0]
        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid)
            if remaining > 0:
                s = next_seq()
                book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': s, 'active': True}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, s, oid))
                else:
                    heapq.heappush(sell_heap, (price, s, oid))
            else:
                # fully filled, record as inactive (not resting)
                s = next_seq()
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': s, 'active': False}
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            match_incoming(side, price, qty, oid)
            # discard remainder, mark as not active/resting
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': next_seq(), 'active': False}
        elif typ == 'market':
            _, oid, side, qty = order
            match_incoming(side, None, qty, oid)
            book[oid] = {'side': side, 'price': None, 'qty': 0, 'seq': next_seq(), 'active': False}
        elif typ == 'cancel':
            _, oid = order
            rec = book.get(oid)
            if rec is not None and rec['active'] and rec['qty'] > 0:
                rec['active'] = False

    return trades

